from h import *
R=[]
R.append((6977081,{
"es":L("Ejotes asados con limón y ajonjolí",
"El limón y el ajonjolí aportan un toque de frescura y un sabor a nuez que se encuentra a menudo en los platillos mediterráneos, mientras que el ajonjolí también es un ingrediente común en muchas cocinas asiáticas; juntos crean una deliciosa fusión de sabores en este acompañamiento de ejotes.",
"4","1/2 taza",
["1 libra de ejotes frescos (con los extremos recortados)","2 cucharadas de aceite de oliva","1/4 cucharadita de sal","1/4 cucharadita de pimienta negra","1 cucharada de ralladura de limón","1 cucharada de semillas de ajonjolí","1 diente de ajo (picado)"],
["Precaliente el horno a 425 grados F. Forre una bandeja para hornear con papel pergamino.","En un tazón grande, mezcle los ejotes con el aceite de oliva, la sal y la pimienta hasta que queden bien cubiertos.","Extienda los ejotes en una sola capa sobre la bandeja preparada.","Espolvoree la ralladura de limón, las semillas de ajonjolí y el ajo picado sobre los ejotes.","Hornee durante 15 minutos, o hasta que los ejotes estén tiernos pero crujientes y ligeramente caramelizados."]),
"ar":L("فاصولياء خضراء محمّصة بالليمون والسمسم",
"يضفي الليمون والسمسم لمسة من الانتعاش ونكهة المكسرات التي نجدها كثيرًا في الأطباق المتوسطية، كما أن السمسم مكوّن شائع في كثير من المطابخ الآسيوية، فيجتمعان معًا في مزيج لذيذ من النكهات في طبق الفاصولياء الخضراء الجانبي هذا.",
"4","½ كوب",
["1 رطل فاصولياء خضراء طازجة (مقصوصة الأطراف)","2 ملعقة كبيرة زيت زيتون","¼ ملعقة صغيرة ملح","¼ ملعقة صغيرة فلفل أسود","1 ملعقة كبيرة قشر ليمون مبشور","1 ملعقة كبيرة بذور سمسم","1 فص ثوم (مفروم)"],
["سخّن الفرن مسبقًا إلى 425° فهرنهايت (220° مئوية). افرش صينية الخَبز بورق زبدة.","في وعاء كبير، اخلط الفاصولياء الخضراء مع زيت الزيتون والملح والفلفل حتى تتغطى جيدًا.","وزّع الفاصولياء الخضراء في طبقة واحدة على الصينية المجهزة.","رشّ قشر الليمون المبشور وبذور السمسم والثوم المفروم فوق الفاصولياء الخضراء.","حمّصها في الفرن لمدة 15 دقيقة، أو حتى تصبح الفاصولياء طرية ومقرمشة قليلًا ومكرملة بعض الشيء."])}))
R.append((6977174,{
"es":L("Sopa de pavo y cebada",
"Esta sopa es una excelente manera de aprovechar el pavo sobrante de Acción de Gracias; también puede usar pollo cocido u otra proteína cocida. Es rápida y fácil de preparar, y rinde lo suficiente para una multitud (o para tener muchas sobras para preparar comidas con anticipación). La cebada aporta un sabor a nuez y una textura masticable, pero puede usar otro cereal como arroz integral o quinua.",
"5","2 tazas",
["1 cucharada de aceite de oliva","1 cebolla mediana (pelada y picada en cubos)","2 zanahorias medianas (picadas en cubos; aproximadamente 1 1/2 tazas)","2 tallos de apio (picados en cubos)","8 onzas de champiñones rebanados","1/2 taza de cebada de cocción rápida","4 tazas de caldo de pollo bajo en sodio y sin grasa","2 tazas de agua","2 tazas (aproximadamente 10 onzas) de pechuga de pavo cocida (deshebrada o picada en cubos)","1/2 cucharadita de sal","1/2 cucharadita de pimienta negra molida"],
["Agregue el aceite de oliva a una olla para sopa a fuego medio-alto.","Agregue la cebolla, las zanahorias, el apio y los champiñones a la olla. Sofría de 8 a 10 minutos, o hasta que la cebolla empiece a ponerse transparente.","Agregue la cebada, el caldo y el agua. Deje que hierva, luego reduzca el fuego y cocine a fuego lento durante 15 minutos.","Agregue el pavo. Sazone con la sal y la pimienta. Cocine hasta que el pavo esté caliente y sirva."]),
"ar":L("حساء الديك الرومي والشعير",
"هذا الحساء طريقة رائعة للاستفادة من بقايا الديك الرومي من عشاء عيد الشكر، أو يمكنك استخدام دجاج مطبوخ أو أي بروتين مطبوخ آخر. وهو سريع وسهل التحضير، ويكفي لعدد كبير من الأشخاص (أو يترك لك كمية وفيرة من الباقي لتحضير الوجبات مسبقًا). يمنح الشعير نكهة تشبه المكسرات وقوامًا مطاطيًا، لكن يمكنك استخدام حبوب أخرى مثل الأرز البني أو الكينوا.",
"5","2 كوب",
["1 ملعقة كبيرة زيت زيتون","1 حبة بصل متوسطة (مقشرة ومقطعة مكعبات)","2 حبة جزر متوسطة (مقطعة مكعبات؛ حوالي 1½ كوب)","2 ساق كرفس (مقطعة مكعبات)","8 أونصة فطر مقطع شرائح","½ كوب شعير سريع الطهي","4 كوب مرق دجاج قليل الصوديوم وخالٍ من الدهون","2 كوب ماء","2 كوب (حوالي 10 أونصة) صدر ديك رومي مطبوخ (مفتّت أو مقطع مكعبات)","½ ملعقة صغيرة ملح","½ ملعقة صغيرة فلفل أسود مطحون"],
["ضع زيت الزيتون في قدر حساء على نار متوسطة إلى عالية.","أضف البصل والجزر والكرفس والفطر إلى القدر. قلّبها لمدة 8 إلى 10 دقائق، أو حتى يبدأ البصل في الشفافية.","أضف الشعير والمرق والماء. اتركها حتى تغلي، ثم خفّف النار واتركها على نار هادئة لمدة 15 دقيقة.","أضف الديك الرومي. تبّل بالملح والفلفل. اطهِ حتى يسخن الديك الرومي، ثم قدّم الحساء."])}))
R.append((6978167,{
"ar":L("سلطة الحمص السريعة",
"تُعدّ الفاصولياء والبقوليات من أصحّ الكربوهيدرات التي يمكنك تناولها مع مرض السكري. يقول معظم الناس إنهم يحبون الفاصولياء، لكنهم لا يعرفون كيف يُدخلون المزيد منها في نظامهم الغذائي. جرّب هذه السلطة اللذيذة الغنية بالألياف والبروتين والنكهة!",
"5","½ كوب",
["1 علبة (15.5 أونصة) حمص (مشطوف ومصفّى)","1 حبة فلفل رومي أحمر متوسطة (مقطعة مكعبات صغيرة جدًا)","1 حبة فلفل رومي أخضر متوسطة (مقطعة مكعبات صغيرة جدًا)","½ حبة بصل أحمر صغيرة (مقطعة مكعبات صغيرة جدًا)","¼ كوب كزبرة خضراء طازجة (مفرومة)","½ حبة ليمون متوسطة (معصورة)","2 ملعقة كبيرة زيت زيتون","1 فص ثوم (مفروم)","¼ ملعقة صغيرة فلفل أسود","¼ ملعقة صغيرة فلفل أحمر (مجروش، اختياري)"],
["في وعاء سلطة متوسط، اخلط جميع مكونات السلطة معًا.","في وعاء صغير، اخفق مكونات الصلصة معًا. اسكبها فوق خليط الحمص وقلّب حتى يتغطى جيدًا."])}))
R.append((6978207,{
"ar":L("أسياخ كرات اللحم",
"تُعدّ كرات اللحم هذه وجبة عائلية ممتعة. ويمكنك أيضًا تقديمها في طبق كمقبلات في المرة القادمة التي تستضيف فيها ضيوفًا.",
"6","2 سيخ",
["1 بخّة، 0.25 غرام بخاخ طهي غير لاصق","½ ملعقة صغيرة ملح (اختياري)","16 أونصة ديك رومي مفروم قليل الدهن (خالٍ من الدهون بنسبة 93%)","2 فص ثوم (مفروم)","2 ملعقة كبيرة جبن بارميزان (مبشور)","2 بياض بيض كبير","¼ ملعقة صغيرة فلفل أسود","8 أونصة فطر كريميني (بيبي بيلا) (طازج، يُقطع إلى نصفين إذا لزم للحصول على 12 قطعة)","24 حبة طماطم عنبية أو كرزية كاملة","1 حبة بصل متوسطة","¼ كوب خل بلسمي","1 ملعقة صغيرة زيت زيتون","12 سيخ خيزران كامل"],
["سخّن الفرن مسبقًا إلى 375° فهرنهايت (190° مئوية). ادهن صينية الخَبز ببخاخ الطهي. ضعها جانبًا.","اخلط بياض البيض وجبن البارميزان والثوم والديك الرومي المفروم والملح (اختياري) والفلفل. اخلط جيدًا وشكّل 12 كرة لحم. ضع كرات اللحم في الثلاجة لمدة 30 دقيقة على الأقل.","لتحضير البصل، اقطعه إلى نصفين. اقطع كل نصف إلى أربعة أجزاء. ثم اقطع كل ربع إلى 3 أقسام، ليصبح المجموع 12 قطعة من البصل.","اغرز في كل سيخ 2 من كرات اللحم و2 من الطماطم و1 قطعة فطر و1 قطعة بصل بالتناوب.","في وعاء صغير، اخفق الخل البلسمي مع زيت الزيتون.","ضع الأسياخ على صينية الخَبز وافرشها من جميع الجوانب بخليط الخل البلسمي وزيت الزيتون. احتفظ بالتتبيلة.","اخبز الأسياخ لمدة 10 دقائق. افرشها من جميع الجوانب بالتتبيلة مرة أخرى واخبزها 10 إلى 15 دقيقة إضافية. يجب أن تصل درجة الحرارة الداخلية لكرات اللحم إلى 165° فهرنهايت (75° مئوية) على الأقل."])}))
